<div class="table-responsive"><table class="table admin-table align-middle mb-0"><thead><tr><th>GRUPO / CURSO</th><th><?= $columnaRecurso === 'aula' ? 'AULA' : 'INSTRUCTOR' ?></th><th>FECHAS</th><th>HORARIOS</th><th>ESTADO</th><th class="admin-actions">ACCIONES</th></tr></thead><tbody>
    <?php if (!$grupos): ?><tr><td colspan="6" class="text-center py-5">No hay grupos asignados.</td></tr><?php endif; ?>
    <?php foreach ($grupos as $grupo): ?><tr><td class="admin-name-cell"><strong>#<?= (int) $grupo['id_grupo'] ?> · <?= $e($grupo['curso']) ?></strong></td><td><?= $e($grupo[$columnaRecurso]) ?></td><td class="text-nowrap"><?= $e($grupo['fecha_inicio']) ?><br><?= $e($grupo['fecha_fin'] ?: 'Sin fin definido') ?></td><td><?php foreach ($grupo['horarios'] as $h): ?><small class="d-block text-nowrap"><?= $e($h['dia_semana'] . ' ' . $h['hora_inicio'] . '–' . $h['hora_fin']) ?></small><?php endforeach; ?><?= !$grupo['horarios'] ? 'Por definir' : '' ?></td><td><?= $e(ucfirst($grupo['estado'])) ?></td><td class="admin-actions text-nowrap"><a href="/admin/grupos/<?= (int) $grupo['id_grupo'] ?>" class="btn admin-icon-btn admin-edit" aria-label="Ver grupo #<?= (int) $grupo['id_grupo'] ?>" title="Ver grupo"><i class="bi bi-eye"></i></a><a href="/admin/grupos?editar=<?= (int) $grupo['id_grupo'] ?>#formulario-grupo" class="btn admin-icon-btn admin-edit" aria-label="Revisar o reasignar grupo #<?= (int) $grupo['id_grupo'] ?>" title="Revisar o reasignar"><i class="bi bi-pencil-square"></i></a></td></tr><?php endforeach; ?>
</tbody></table></div>
